insert into public.store_settings (id, store_name, contact_phone, whatsapp_number, vodafone_cash_number, instapay_number, delivery_fee, hero_title, hero_subtitle, store_description) values ('store', 'SAIF STORE', '0100 000 0000', '201000000000', '0100 000 0000', 'saif.store@instapay', 75, 'اللبس اللي يشبهك.', 'قطع أساسية، معمولة بعناية، عشان تعيش معاك أكتر من موسم.', 'SAIF STORE براند مصري بيحب القطع الهادية، الخامات المظبوطة، والتفاصيل اللي بتبان مع الوقت.') on conflict (id) do update set store_name = excluded.store_name, hero_title = excluded.hero_title, hero_subtitle = excluded.hero_subtitle, store_description = excluded.store_description;
