-- SAIF STORE / curated starter catalog
on conflict (slug) do update set name = excluded.name, description = excluded.description, image_url = excluded.image_url, display_order = excluded.display_order;

on conflict (slug) do update set category_id = excluded.category_id, name = excluded.name, description = excluded.description, price = excluded.price, old_price = excluded.old_price, discount_percent = excluded.discount_percent, sizes = excluded.sizes, colors = excluded.colors, stock = excluded.stock, is_featured = excluded.is_featured, display_order = excluded.display_order, is_active = true;

